package io.knowledgebrain.learning;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import io.knowledgebrain.contracts.learning.githubevidence.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_DATABASE_URL",matches=".+")
class GitHubEvidenceStoreIntegrationTest extends GitHubEvidenceFixtures {
 @BeforeEach void setup(){githubInit();}
 void status(int n,Runnable action){assertEquals(n,assertThrows(ResponseStatusException.class,action::run).getStatusCode().value());}
 @Test void commitPinsMemoLifecycleAndReplaysAreIndependentOfRootSourceAndProgress()throws Exception{String key=key();var root=roadmaps.get(space,roadmap);var progress=study.summary(space,roadmap);var one=github.record(space,roadmap,actor,key,githubInput(),trace,this::ref).evidence();assertEquals(7,one.evidenceId().version());assertEquals("PRIVATE",one.visibility());assertEquals(1,one.commitVersion());assertEquals(ref().sha(),one.sha());assertEquals(one,github.change(space,roadmap,one.evidenceId(),actor,1,one.memo(),false,trace));assertEquals(1,events(one.evidenceId()));var two=github.change(space,roadmap,one.evidenceId(),actor,1,"Corrected private memo",false,trace);assertEquals(one.sha(),two.sha());assertEquals(one.subject(),two.subject());assertEquals(one.importedAt(),two.importedAt());status(412,()->github.change(space,roadmap,one.evidenceId(),actor,1,"stale",false,trace));var retired=github.change(space,roadmap,one.evidenceId(),actor,2,null,true,trace);assertEquals(retired,github.get(space,roadmap,one.evidenceId()));assertTrue(github.page(space,roadmap,"ACTIVE",null,20).items().isEmpty());assertEquals(List.of(retired),github.page(space,roadmap,"RETIRED",null,20).items());assertEquals(one,github.history(space,roadmap,one.evidenceId(),2,5).getFirst().snapshot());assertEquals(root,roadmaps.get(space,roadmap));assertEquals(progress,study.summary(space,roadmap));roadmaps.metadata(space,roadmap,actor,2,null,null,true,trace);var retry=github.record(space,roadmap,actor,key,githubInput(),trace,()->{fail("Replay must not reread source");return null;});assertFalse(retry.created());assertEquals(retired,retry.evidence());assertEquals(3,events(one.evidenceId()));status(409,()->github.record(space,roadmap,actor,key,new GitHubEvidenceStore.Input(node,repo,commit,"Different original request"),trace,this::ref));status(404,()->github.change(space,roadmap,one.evidenceId(),actor,3,"",false,trace));}
 @Test void failedOwnerChecksWrongKindsAndDuplicatePinsNeverPartiallyWrite(){var bad=new GitHubReferenceClient.Reference(actor,actor,repo,commit,"a/b","a".repeat(40),"subject",null,"2020-01-01T00:00:00Z","2026-10-01T00:00:00Z","https://github.com/a/b/commit/"+"a".repeat(40),"PRIVATE","PUBLIC",1);status(503,()->github.record(space,roadmap,actor,key(),githubInput(),trace,()->bad));status(404,()->github.record(space,roadmap,actor,key(),githubInput(),trace,()->{throw new ResponseStatusException(HttpStatus.NOT_FOUND);}));status(404,()->github.record(actor,roadmap,actor,key(),githubInput(),trace,this::ref));status(404,()->github.record(space,roadmap,actor,key(),new GitHubEvidenceStore.Input(ids.next(),repo,commit,""),trace,this::ref));status(400,()->github.record(space,roadmap,actor,key(),new GitHubEvidenceStore.Input(node,repo,commit,"가".repeat(2731)),trace,this::ref));assertTrue(github.page(space,roadmap,"ACTIVE",null,100).items().isEmpty());String shared=key();UUID note=ids.next();var legacy=new LearningEvidenceStore(ds,clock,roadmaps);var old=legacy.record(space,roadmap,actor,shared,new LearningEvidenceStore.Input(node,note,1,"Legacy"),trace,()->new NoteReferenceClient.Reference(space,note,actor,1,"Note","PRIVATE")).evidence();status(409,()->github.record(space,roadmap,actor,shared,githubInput(),trace,this::ref));status(404,()->github.get(space,roadmap,old.evidenceId()));var one=github();status(404,()->legacy.get(space,roadmap,one.evidenceId()));status(409,()->github.record(space,roadmap,actor,key(),githubInput(),trace,()->{fail();return null;}));github.change(space,roadmap,one.evidenceId(),actor,1,null,true,trace);var again=github();assertNotEquals(one.evidenceId(),again.evidenceId());assertEquals(0,study.progress(space,roadmap,node).version());}
 @Test void boundedCatalogReverseAndAuditKeepHistoricalLabelsAndCurrentRootTitle(){var entries=new ArrayList<GitHubEvidenceStore.Evidence>();for(int i=0;i<22;i++){UUID c=ids.next();String sha=String.format("%040x",i+1);entries.add(github.record(space,roadmap,actor,key(),new GitHubEvidenceStore.Input(node,repo,c,"Memo"),trace,()->ref(c,sha)).evidence());}var first=github.page(space,roadmap,"ACTIVE",null,20);assertEquals(20,first.items().size());assertEquals(2,github.page(space,roadmap,"ACTIVE",first.nextAfter(),20).items().size());var one=entries.getFirst();for(int version=1;version<8;version++)github.change(space,roadmap,one.evidenceId(),actor,version,"Memo "+version,false,trace);assertEquals(List.of(8L,7L,6L,5L,4L),github.history(space,roadmap,one.evidenceId(),Long.MAX_VALUE,5).stream().map(GitHubEvidenceStore.Revision::version).toList());assertEquals(3,github.history(space,roadmap,one.evidenceId(),4,5).size());roadmaps.metadata(space,roadmap,actor,2,"Current roadmap title","",false,trace);var related=github.related(space,repo,one.commitId(),"ACTIVE",null,20);assertEquals(1,related.items().size());assertEquals("Current roadmap title",related.items().getFirst().roadmapTitle());assertEquals(one.nodeTitle(),related.items().getFirst().nodeTitle());assertTrue(github.related(actor,repo,one.commitId(),"ACTIVE",null,20).items().isEmpty());assertTrue(github.related(space,ids.next(),one.commitId(),"ACTIVE",null,20).items().isEmpty());status(404,()->github.get(actor,roadmap,one.evidenceId()));status(404,()->github.history(space,ids.next(),one.evidenceId(),Long.MAX_VALUE,5));status(400,()->github.page(space,roadmap,"ALL",null,20));status(400,()->github.page(space,roadmap,"ACTIVE",null,101));status(400,()->github.history(space,roadmap,one.evidenceId(),0,5));github.change(space,roadmap,one.evidenceId(),actor,8,null,true,trace);assertTrue(github.related(space,repo,one.commitId(),"ACTIVE",null,20).items().isEmpty());assertEquals(1,github.related(space,repo,one.commitId(),"RETIRED",null,20).items().size());}
 @Test void concurrentRetryAndMemoEditorsSerializeAgainstTheSameRoot()throws Exception{String key=key();var calls=new AtomicInteger();try(var pool=Executors.newFixedThreadPool(2)){var gate=new CyclicBarrier(2);var results=new ArrayList<Future<GitHubEvidenceStore.Recorded>>();for(int i=0;i<2;i++)results.add(pool.submit(()->{gate.await();return github.record(space,roadmap,actor,key,githubInput(),trace,()->{calls.incrementAndGet();return ref();});}));var a=results.get(0).get();var b=results.get(1).get();assertNotEquals(a.created(),b.created());assertEquals(a.evidence(),b.evidence());assertEquals(1,calls.get());var e=a.evidence();var gate2=new CyclicBarrier(2);var versions=new ArrayList<Future<Integer>>();for(String memo:List.of("A","B"))versions.add(pool.submit(()->{gate2.await();try{github.change(space,roadmap,e.evidenceId(),actor,1,memo,false,trace);return 200;}catch(ResponseStatusException error){return error.getStatusCode().value();}}));assertEquals(Set.of(200,412),Set.of(versions.get(0).get(),versions.get(1).get()));assertEquals(2,events(e.evidenceId()));}}
 @Test void sessionPinsAreIndependentAndAllowCleanupAfterEvidenceRetirement(){var e=github();var session=session(node);var root=roadmaps.get(space,roadmap);var progress=study.summary(space,roadmap);var zero=links.get(space,roadmap,e.evidenceId(),"GITHUB");assertEquals(0,zero.version());assertEquals(zero,links.change(space,roadmap,e.evidenceId(),"GITHUB",actor,0,new EvidenceSessionStore.Input(null,null),trace));var one=link(e.evidenceId(),"GITHUB",session,0);assertEquals("GITHUB",one.evidenceKind());assertEquals(session.durationSeconds(),one.durationSeconds());assertEquals(e,github.get(space,roadmap,e.evidenceId()));assertEquals(root,roadmaps.get(space,roadmap));assertEquals(progress,study.summary(space,roadmap));status(404,()->links.get(space,roadmap,e.evidenceId(),"NOTE"));status(409,()->link(e.evidenceId(),"GITHUB",session(otherNode),1));var changed=study.changeSession(space,roadmap,session.sessionId(),actor,1,new LearningStudyStore.Input(node,session.startedAt(),session.endedAt(),"Changed session"),false,trace);assertEquals(one,links.get(space,roadmap,e.evidenceId(),"GITHUB"));assertEquals(one,link(e.evidenceId(),"GITHUB",session,1));var two=link(e.evidenceId(),"GITHUB",changed,1);assertEquals(2L,two.sessionVersion());status(412,()->links.change(space,roadmap,e.evidenceId(),"GITHUB",actor,1,new EvidenceSessionStore.Input(null,null),trace));github.change(space,roadmap,e.evidenceId(),actor,1,null,true,trace);var unlinked=links.change(space,roadmap,e.evidenceId(),"GITHUB",actor,2,new EvidenceSessionStore.Input(null,null),trace);assertEquals(3,unlinked.version());status(404,()->link(e.evidenceId(),"GITHUB",changed,3));assertEquals(one,links.history(space,roadmap,e.evidenceId(),"GITHUB",2,5).getFirst().snapshot());assertEquals(3,events(one.linkId()));roadmaps.metadata(space,roadmap,actor,2,null,null,true,trace);assertEquals(unlinked,links.get(space,roadmap,e.evidenceId(),"GITHUB"));status(404,()->links.change(space,roadmap,e.evidenceId(),"GITHUB",actor,3,new EvidenceSessionStore.Input(null,null),trace));}
 @Test void newWirePinsOriginalSourceAndSessionUsesItsOwnArtifact()throws Exception{var e=github();var event=GitHubLearningEventEnvelopeV1.parseFrom(sql.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,e.evidenceId()));var payload=GitHubEvidenceChangedPayloadV1.parseFrom(event.getPayload());assertEquals("learning-service",event.getProducer());assertEquals("GitHubLearningEvidence",event.getAggregateType());assertEquals(actor.toString(),event.getActorId());assertEquals(space.toString(),event.getSpaceId());assertEquals(repo.toString(),payload.getRepositoryId());assertEquals(commit.toString(),payload.getCommitId());assertEquals(1,payload.getCommitVersion());assertEquals(e.memo(),payload.getMemo());var association=link(e.evidenceId(),"GITHUB",session(node),0);var raw=sql.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,association.linkId());var linked=GitHubLearningEventEnvelopeV1.parseFrom(raw);var p=GitHubEvidenceSessionChangedPayloadV1.parseFrom(linked.getPayload());assertEquals("GITHUB",p.getEvidenceKind());assertEquals("GitHubEvidenceStudySession",linked.getAggregateType());assertEquals(e.evidenceId().toString(),p.getEvidenceId());assertEquals("github-evidence-session-events",sql.queryForObject("SELECT schema_artifact FROM outbox_event WHERE aggregateid=?",String.class,association.linkId()));assertEquals(0,sql.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid=? AND aggregatetype='evidence-session'",Integer.class,association.linkId()));}
}
